final crypto = AdbCrypto(adbKeyName: 'my-app@dart');
final conn = AdbConnection('192.168.1.10', 5555, crypto, verbose: true);
await conn.connect();
final shell = await conn.openShell();
shell.onPayload.listen((p) => print(utf8.decode(p)));
await shell.writeString('pm list packages\n');
await shell.sendClose();
await conn.disconnect();
